  it("dequantize works with BYTE", function() {
    const input = [-127, -127, -127, 0, 0, 0, 127, 127, 127];
    const expected = [-1, -1, -1, 0, 0, 0, 1, 1, 1];
    const result = AttributeCompression_default.dequantize(
      new Int8Array(input),
      ComponentDatatype_default.BYTE,
      AttributeType_default.VEC3,
      3
    );
    for (let i = 0; i < input.length; i++) {
      expect(result[i]).toEqualEpsilon(expected[i], Math_default.EPSILON2);
    }
  });
