  it("decodeRGB8 decodes", function() {
    const { decodeRGB8 } = AttributeCompression_default;
    const color = new Color_default();
    expect(decodeRGB8(0, color)).toEqual(Color_default.BLACK);
    expect(decodeRGB8(16711680, color)).toEqual(Color_default.RED);
    expect(decodeRGB8(32768, color)).toEqual(Color_default.GREEN);
    expect(decodeRGB8(255, color)).toEqual(Color_default.BLUE);
    expect(decodeRGB8(16777215, color)).toEqual(Color_default.WHITE);
    expect(decodeRGB8(14524637, color)).toEqual(Color_default.PLUM);
  });
