// packages/core/Specs/AxisAlignedBoundingBoxSpec.js
describe("Core/AxisAlignedBoundingBox", function() {
  const positions = [
    new Cartesian3_default(3, -1, -3),
    new Cartesian3_default(2, -2, -2),
    new Cartesian3_default(1, -3, -1),
    new Cartesian3_default(0, 0, 0),
    new Cartesian3_default(-1, 1, 1),
    new Cartesian3_default(-2, 2, 2),
    new Cartesian3_default(-3, 3, 3)
  ];
  const positionsMinimum = new Cartesian3_default(-3, -3, -3);
  const positionsMaximum = new Cartesian3_default(3, 3, 3);
  const positionsCenter = new Cartesian3_default(0, 0, 0);
  it("constructor sets expected default values", function() {
    const box = new AxisAlignedBoundingBox_default();
    expect(box.minimum).toEqual(Cartesian3_default.ZERO);
    expect(box.maximum).toEqual(Cartesian3_default.ZERO);
    expect(box.center).toEqual(Cartesian3_default.ZERO);
  });
  it("constructor sets expected parameter values", function() {
    const minimum = new Cartesian3_default(1, 2, 3);
    const maximum = new Cartesian3_default(4, 5, 6);
    const center = new Cartesian3_default(2.5, 3.5, 4.5);
    const box = new AxisAlignedBoundingBox_default(minimum, maximum, center);
    expect(box.minimum).toEqual(minimum);
    expect(box.maximum).toEqual(maximum);
    expect(box.center).toEqual(center);
  });
  it("constructor computes center if not supplied", function() {
    const minimum = new Cartesian3_default(1, 2, 3);
    const maximum = new Cartesian3_default(4, 5, 6);
    const expectedCenter = new Cartesian3_default(2.5, 3.5, 4.5);
    const box = new AxisAlignedBoundingBox_default(minimum, maximum);
    expect(box.minimum).toEqual(minimum);
    expect(box.maximum).toEqual(maximum);
    expect(box.center).toEqual(expectedCenter);
  });
  it("fromCorners works with a result parameter", function() {
    const minimum = new Cartesian3_default(0, 0, 0);
    const maximum = new Cartesian3_default(1, 1, 1);
    const expectedCenter = new Cartesian3_default(0.5, 0.5, 0.5);
    const box = new AxisAlignedBoundingBox_default();
    const result = AxisAlignedBoundingBox_default.fromCorners(minimum, maximum, box);
    expect(result.minimum).toEqual(minimum);
    expect(result.maximum).toEqual(maximum);
    expect(result.center).toEqual(expectedCenter);
    expect(result).toBe(box);
  });
  it("fromCorners works without a result parameter", function() {
    const minimum = new Cartesian3_default(0, 0, 0);
    const maximum = new Cartesian3_default(1, 1, 1);
    const expectedCenter = new Cartesian3_default(0.5, 0.5, 0.5);
    const box = AxisAlignedBoundingBox_default.fromCorners(minimum, maximum);
    expect(box.minimum).toEqual(minimum);
    expect(box.maximum).toEqual(maximum);
    expect(box.center).toEqual(expectedCenter);
  });
  it("fromCorners throws without a minimum", function() {
    expect(function() {
      AxisAlignedBoundingBox_default.fromCorners(void 0, Cartesian3_default.ZERO);
    }).toThrowDeveloperError();
  });
  it("fromCorners throws without a maximum", function() {
    expect(function() {
      AxisAlignedBoundingBox_default.fromCorners(Cartesian3_default.ZERO, void 0);
    }).toThrowDeveloperError();
  });
  it("fromPoints constructs empty box with undefined positions", function() {
    const box = AxisAlignedBoundingBox_default.fromPoints(void 0);
    expect(box.minimum).toEqual(Cartesian3_default.ZERO);
    expect(box.maximum).toEqual(Cartesian3_default.ZERO);
    expect(box.center).toEqual(Cartesian3_default.ZERO);
  });
  it("fromPoints constructs empty box with empty positions", function() {
    const box = AxisAlignedBoundingBox_default.fromPoints([]);
    expect(box.minimum).toEqual(Cartesian3_default.ZERO);
    expect(box.maximum).toEqual(Cartesian3_default.ZERO);
    expect(box.center).toEqual(Cartesian3_default.ZERO);
  });
  it("fromPoints computes the correct values", function() {
    const box = AxisAlignedBoundingBox_default.fromPoints(positions);
    expect(box.minimum).toEqual(positionsMinimum);
    expect(box.maximum).toEqual(positionsMaximum);
    expect(box.center).toEqual(positionsCenter);
  });
  it("clone without a result parameter", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.UNIT_Y,
      Cartesian3_default.UNIT_X
    );
    const result = box.clone();
    expect(box).not.toBe(result);
    expect(box).toEqual(result);
  });
  it("clone without a result parameter with box of offset center", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.UNIT_Y,
      Cartesian3_default.UNIT_X,
      Cartesian3_default.UNIT_Z
    );
    const result = box.clone();
    expect(box).not.toBe(result);
    expect(box).toEqual(result);
  });
  it("clone with a result parameter", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.UNIT_Y,
      Cartesian3_default.UNIT_X
    );
    const result = new AxisAlignedBoundingBox_default(
      Cartesian3_default.ZERO,
      Cartesian3_default.UNIT_Z
    );
    const returnedResult = box.clone(result);
    expect(result).toBe(returnedResult);
    expect(box).not.toBe(result);
    expect(box).toEqual(result);
  });
  it('clone works with "this" result parameter', function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.UNIT_Y,
      Cartesian3_default.UNIT_X
    );
    const returnedResult = box.clone(box);
    expect(box).toBe(returnedResult);
    expect(box.minimum).toEqual(Cartesian3_default.UNIT_Y);
    expect(box.maximum).toEqual(Cartesian3_default.UNIT_X);
  });
  it("equals works in all cases", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.UNIT_X,
      Cartesian3_default.UNIT_Y,
      Cartesian3_default.UNIT_Z
    );
    const bogie = new Cartesian3_default(2, 3, 4);
    expect(
      box.equals(
        new AxisAlignedBoundingBox_default(
          Cartesian3_default.UNIT_X,
          Cartesian3_default.UNIT_Y,
          Cartesian3_default.UNIT_Z
        )
      )
    ).toEqual(true);
    expect(
      box.equals(
        new AxisAlignedBoundingBox_default(bogie, Cartesian3_default.UNIT_Y, Cartesian3_default.UNIT_Y)
      )
    ).toEqual(false);
    expect(
      box.equals(
        new AxisAlignedBoundingBox_default(Cartesian3_default.UNIT_X, bogie, Cartesian3_default.UNIT_Z)
      )
    ).toEqual(false);
    expect(
      box.equals(
        new AxisAlignedBoundingBox_default(Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y, bogie)
      )
    ).toEqual(false);
    expect(box.equals(void 0)).toEqual(false);
  });
  it("computes the bounding box for a single position", function() {
    const box = AxisAlignedBoundingBox_default.fromPoints([positions[0]]);
    expect(box.minimum).toEqual(positions[0]);
    expect(box.maximum).toEqual(positions[0]);
    expect(box.center).toEqual(positions[0]);
  });
  it("intersectPlane works with box on the positive side of a plane", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.negate(Cartesian3_default.UNIT_X, new Cartesian3_default()),
      Cartesian3_default.ZERO
    );
    const normal2 = Cartesian3_default.negate(Cartesian3_default.UNIT_X, new Cartesian3_default());
    const position = Cartesian3_default.UNIT_X;
    const plane = new Plane_default(normal2, -Cartesian3_default.dot(normal2, position));
    expect(box.intersectPlane(plane)).toEqual(Intersect_default.INSIDE);
  });
  it("intersectPlane works with box on the negative side of a plane", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.negate(Cartesian3_default.UNIT_X, new Cartesian3_default()),
      Cartesian3_default.ZERO
    );
    const normal2 = Cartesian3_default.UNIT_X;
    const position = Cartesian3_default.UNIT_X;
    const plane = new Plane_default(normal2, -Cartesian3_default.dot(normal2, position));
    expect(box.intersectPlane(plane)).toEqual(Intersect_default.OUTSIDE);
  });
  it("intersectPlane works with box intersecting a plane", function() {
    const box = new AxisAlignedBoundingBox_default(
      Cartesian3_default.ZERO,
      Cartesian3_default.multiplyByScalar(Cartesian3_default.UNIT_X, 2, new Cartesian3_default())
    );
    const normal2 = Cartesian3_default.UNIT_X;
    const position = Cartesian3_default.UNIT_X;
    const plane = new Plane_default(normal2, -Cartesian3_default.dot(normal2, position));
    expect(box.intersectPlane(plane)).toEqual(Intersect_default.INTERSECTING);
  });
  it("clone returns undefined with no parameter", function() {
    expect(AxisAlignedBoundingBox_default.clone()).toBeUndefined();
  });
  it("intersectPlane throws without a box", function() {
    const plane = new Plane_default(Cartesian3_default.UNIT_X, 0);
    expect(function() {
      AxisAlignedBoundingBox_default.intersectPlane(void 0, plane);
    }).toThrowDeveloperError();
  });
  it("intersectPlane throws without a plane", function() {
    const box = new AxisAlignedBoundingBox_default();
    expect(function() {
      AxisAlignedBoundingBox_default.intersectPlane(box, void 0);
    }).toThrowDeveloperError();
  });
});

// packages/core/Specs/barycentricCoordinatesSpec.js
describe("Core/barycentricCoordinates", function() {
  const p0 = new Cartesian3_default(-1, 0, 0);
  const p1 = new Cartesian3_default(1, 0, 0);
  const p2 = new Cartesian3_default(0, 1, 1);
  it("evaluates to p0", function() {
    const point = Cartesian3_default.clone(p0);
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      Cartesian3_default.UNIT_X
    );
  });
  it("evaluates to p1", function() {
    const point = Cartesian3_default.clone(p1);
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      Cartesian3_default.UNIT_Y
    );
  });
  it("evaluates to p2", function() {
    const point = Cartesian3_default.clone(p2);
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      Cartesian3_default.UNIT_Z
    );
  });
  it("evaluates on the p0-p1 edge", function() {
    const point = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.add(p1, p0, new Cartesian3_default()),
      0.5,
      new Cartesian3_default()
    );
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      new Cartesian3_default(0.5, 0.5, 0)
    );
  });
  it("evaluates on the p0-p2 edge", function() {
    const point = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.add(p2, p0, new Cartesian3_default()),
      0.5,
      new Cartesian3_default()
    );
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      new Cartesian3_default(0.5, 0, 0.5)
    );
  });
  it("evaluates on the p1-p2 edge", function() {
    const point = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.add(p2, p1, new Cartesian3_default()),
      0.5,
      new Cartesian3_default()
    );
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqual(
      new Cartesian3_default(0, 0.5, 0.5)
    );
  });
  it("evaluates on the interior", function() {
    const scalar = 1 / 3;
    const point = Cartesian3_default.multiplyByScalar(
      Cartesian3_default.add(
        Cartesian3_default.add(p0, p1, new Cartesian3_default()),
        p2,
        new Cartesian3_default()
      ),
      scalar,
      new Cartesian3_default()
    );
    expect(barycentricCoordinates_default(point, p0, p1, p2)).toEqualEpsilon(
      new Cartesian3_default(scalar, scalar, scalar),
      Math_default.EPSILON14
    );
  });
  it("returns undefined for colinear points", function() {
    const p02 = new Cartesian3_default(-1, -1, 0);
    const p12 = new Cartesian3_default(0, 0, 0);
    const p22 = new Cartesian3_default(1, 1, 0);
    const point = new Cartesian3_default(0.5, 0.5, 0);
    const coord = barycentricCoordinates_default(point, p02, p12, p22);
    expect(coord).toBeUndefined();
  });
  it("evaluates with equal length sides", function() {
    const p02 = new Cartesian3_default(
      9635312487071484,
      13827945400273020,
      -16479219993905144
    );
    const p12 = new Cartesian3_default(
      12832234180639317e-9,
      -10455085701705107e-9,
      750010.7274386138
    );
    const p22 = new Cartesian3_default(
      -968901110628853e-8,
      -13420063892507521e-9,
      750010.7274386119
    );
    expect(barycentricCoordinates_default(p02, p02, p12, p22)).toEqual(Cartesian3_default.UNIT_X);
    expect(barycentricCoordinates_default(p12, p02, p12, p22)).toEqual(Cartesian3_default.UNIT_Y);
    expect(barycentricCoordinates_default(p22, p02, p12, p22)).toEqual(Cartesian3_default.UNIT_Z);
  });
  it("throws without point", function() {
    expect(function() {
      barycentricCoordinates_default();
    }).toThrowDeveloperError();
  });
  it("throws without p0", function() {
    expect(function() {
      barycentricCoordinates_default(new Cartesian3_default());
    }).toThrowDeveloperError();
  });
  it("throws without p1", function() {
    expect(function() {
      barycentricCoordinates_default(new Cartesian3_default(), new Cartesian3_default());
    }).toThrowDeveloperError();
  });
  it("throws without p2", function() {
    expect(function() {
      barycentricCoordinates_default(
        new Cartesian3_default(),
        new Cartesian3_default(),
        new Cartesian3_default()
      );
    }).toThrowDeveloperError();
  });
});

// packages/core/Specs/binarySearchSpec.js
describe("Core/binarySearch", function() {
  it("can perform a binary search for 0", function() {
    const array = [0, 1, 2, 3, 4, 5, 6, 7];
    const toFind = 0;
    const index = binarySearch_default(array, toFind, function(a, b) {
      return a - b;
    });
    expect(index).toEqual(0);
  });
  it("can perform a binary search for item in the list", function() {
    const array = [0, 1, 2, 3, 4, 5, 6, 7];
    const toFind = 7;
    const index = binarySearch_default(array, toFind, function(a, b) {
      return a - b;
    });
    expect(index).toEqual(7);
  });
  it("can perform a binary search for item in between two items in the list", function() {
    const array = [0, 1, 2, 3, 4, 5, 6, 7];
    const toFind = 3.5;
    const index = binarySearch_default(array, toFind, function(a, b) {
      return a - b;
    });
    expect(~index).toEqual(4);
  });
  it("can perform a binary search for item before all items in the list", function() {
    const array = [0, 1, 2, 3, 4, 5, 6, 7];
    const toFind = -2;
    const index = binarySearch_default(array, toFind, function(a, b) {
      return a - b;
    });
    expect(~index).toEqual(0);
  });
  it("can perform a binary search for item after all items in the list", function() {
    const array = [0, 1, 2, 3, 4, 5, 6, 7];
    const toFind = 12;
    const index = binarySearch_default(array, toFind, function(a, b) {
      return a - b;
    });
    expect(~index).toEqual(8);
  });
  function dummy() {
    return true;
  }
  it("throws an exception if array is missing", function() {
    expect(function() {
      binarySearch_default(void 0, 1, dummy);
    }).toThrowDeveloperError();
  });
  it("throws an exception if itemToFind is missing", function() {
    expect(function() {
      binarySearch_default([0, 1, 2], void 0, dummy);
    }).toThrowDeveloperError();
  });
  it("throws an exception if comparator is missing", function() {
    expect(function() {
      binarySearch_default([0, 1, 2], 1, void 0);
    }).toThrowDeveloperError();
  });
});

// Specs/createPackableSpecs.js
function createPackableSpecs(packable, instance, packedInstance, namePrefix) {
  namePrefix = namePrefix ?? "";
  it(`${namePrefix} can pack`, function() {
    const packedArray = [];
    const returnArray = packable.pack(instance, packedArray);
    expect(returnArray).toBe(packedArray);
    const packedLength = defined_default(packable.packedLength) ? packable.packedLength : instance.packedLength;
    expect(packedArray.length).toEqual(packedLength);
    expect(packedArray).toEqualEpsilon(packedInstance, Math_default.EPSILON15);
  });
  it(`${namePrefix} can roundtrip`, function() {
    const packedArray = [];
    packable.pack(instance, packedArray);
    const result = packable.unpack(packedArray);
    expect(instance).toEqual(result);
  });
  it(`${namePrefix} can unpack`, function() {
    const result = packable.unpack(packedInstance);
    expect(result).toEqual(instance);
  });
  it(`${namePrefix} can pack with startingIndex`, function() {
    const packedArray = [0];
    const expected = packedArray.concat(packedInstance);
    packable.pack(instance, packedArray, 1);
    expect(packedArray).toEqualEpsilon(expected, Math_default.EPSILON15);
  });
  it(`${namePrefix} can unpack with startingIndex`, function() {
    const packedArray = [0].concat(packedInstance);
    const result = packable.unpack(packedArray, 1);
    expect(instance).toEqual(result);
  });
  it(`${namePrefix} pack throws with undefined value`, function() {
    const array = [];
    expect(function() {
      packable.pack(void 0, array);
    }).toThrowDeveloperError();
  });
  it(`${namePrefix} pack throws with undefined array`, function() {
    expect(function() {
      packable.pack(instance, void 0);
    }).toThrowDeveloperError();
  });
  it(`${namePrefix} unpack throws with undefined array`, function() {
    expect(function() {
      packable.unpack(void 0);
    }).toThrowDeveloperError();
  });
  if (typeof packable.convertPackedArrayForInterpolation === "function") {
    it(`${namePrefix} packs and unpacks for interpolation.`, function() {
      const packedForInterpolation = [];
      packable.convertPackedArrayForInterpolation(
        packedInstance,
        0,
        0,
        packedForInterpolation
      );
      const value = packable.unpackInterpolationResult(
        packedForInterpolation,
        packedInstance,
        0,
        0
      );
      const result = packable.unpack(packedInstance);
      expect(value).toEqual(result);
    });
    it(`${namePrefix} convertPackedArrayForInterpolation throws without array.`, function() {
      expect(function() {
        packable.convertPackedArrayForInterpolation(void 0);
      }).toThrowDeveloperError();
    });
    it(`${namePrefix} unpackInterpolationResult throws without packed array.`, function() {
      expect(function() {
        packable.unpackInterpolationResult(void 0, []);
      }).toThrowDeveloperError();
    });
    it(`${namePrefix} unpackInterpolationResult throws without source array.`, function() {
      expect(function() {
        packable.unpackInterpolationResult([], void 0);
      }).toThrowDeveloperError();
    });
  }
}
var createPackableSpecs_default = createPackableSpecs;

