  it("equalsEpsilon", function() {
    let cartesian14 = new Cartesian3_default(1, 2, 3);
    expect(cartesian14.equalsEpsilon(new Cartesian3_default(1, 2, 3), 0)).toEqual(
      true
    );
    expect(cartesian14.equalsEpsilon(new Cartesian3_default(1, 2, 3), 1)).toEqual(
      true
    );
    expect(cartesian14.equalsEpsilon(new Cartesian3_default(2, 2, 3), 1)).toEqual(
      true
    );
    expect(cartesian14.equalsEpsilon(new Cartesian3_default(1, 3, 3), 1)).toEqual(
      true
    );
    expect(cartesian14.equalsEpsilon(new Cartesian3_default(1, 2, 4), 1)).toEqual(
      true
    );
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(2, 2, 3),
        Math_default.EPSILON6
      )
    ).toEqual(false);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(1, 3, 3),
        Math_default.EPSILON6
      )
    ).toEqual(false);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(1, 2, 4),
        Math_default.EPSILON6
      )
    ).toEqual(false);
    expect(cartesian14.equalsEpsilon(void 0, 1)).toEqual(false);
    cartesian14 = new Cartesian3_default(3e6, 4e6, 5e6);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(3e6, 4e6, 5e6),
        0
      )
    ).toEqual(true);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(30000002e-1, 4e6, 5e6),
        Math_default.EPSILON7
      )
    ).toEqual(true);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(3e6, 40000002e-1, 5e6),
        Math_default.EPSILON7
      )
    ).toEqual(true);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(3e6, 4e6, 50000002e-1),
        Math_default.EPSILON7
      )
    ).toEqual(true);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(30000002e-1, 40000002e-1, 50000002e-1),
        Math_default.EPSILON7
      )
    ).toEqual(true);
    expect(
      cartesian14.equalsEpsilon(
        new Cartesian3_default(30000002e-1, 40000002e-1, 50000002e-1),
        Math_default.EPSILON9
      )
    ).toEqual(false);
    expect(cartesian14.equalsEpsilon(void 0, 1)).toEqual(false);
    expect(Cartesian3_default.equalsEpsilon(void 0, cartesian14, 1)).toEqual(false);
  });
