// packages/core/Specs/createGuidSpec.js
describe("Core/createGuid", function() {
  it("creates GUIDs", function() {
    const isGuidRegex = /^(\{){0,1}[0-9a-fA-F]{8}\-[0-9a-fA-F]{4}\-[0-9a-fA-F]{4}\-[0-9a-fA-F]{4}\-[0-9a-fA-F]{12}(\}){0,1}$/;
    const guid1 = createGuid_default();
    const guid2 = createGuid_default();
    const guid3 = createGuid_default();
    expect(guid1).not.toEqual(guid2);
    expect(guid1).not.toEqual(guid3);
    expect(guid2).not.toEqual(guid3);
    expect(isGuidRegex.test(guid1)).toEqual(true);
    expect(guid1.length).toEqual(36);
    expect(isGuidRegex.test(guid2)).toEqual(true);
    expect(guid2.length).toEqual(36);
    expect(isGuidRegex.test(guid3)).toEqual(true);
    expect(guid3.length).toEqual(36);
  });
});

// packages/core/Specs/CubicRealPolynomialSpec.js
describe("Core/CubicRealPolynomial", function() {
  it("discriminant throws without a", function() {
    expect(function() {
      CubicRealPolynomial_default.computeDiscriminant();
    }).toThrowDeveloperError();
  });
  it("discriminant throws without b", function() {
    expect(function() {
      CubicRealPolynomial_default.computeDiscriminant(1);
    }).toThrowDeveloperError();
  });
  it("discriminant throws without c", function() {
    expect(function() {
      CubicRealPolynomial_default.computeDiscriminant(1, 1);
    }).toThrowDeveloperError();
  });
  it("discriminant throws without d", function() {
    expect(function() {
      CubicRealPolynomial_default.computeDiscriminant(1, 1, 1);
    }).toThrowDeveloperError();
  });
  it("discriminant", function() {
    const a = 3;
    const b = 2;
    const c = 1;
    const d = 1;
    const expected = b * b * c * c - 4 * a * c * c * c - 4 * b * b * b * d - 27 * a * a * d * d + 18 * a * b * c * d;
    const actual = CubicRealPolynomial_default.computeDiscriminant(a, b, c, d);
    expect(actual).toEqualEpsilon(expected, Math_default.EPSILON14);
  });
  it("real roots throws without a", function() {
    expect(function() {
      CubicRealPolynomial_default.computeRealRoots();
    }).toThrowDeveloperError();
  });
  it("real roots throws without b", function() {
    expect(function() {
      CubicRealPolynomial_default.computeRealRoots(1);
    }).toThrowDeveloperError();
  });
  it("real roots throws without c", function() {
    expect(function() {
      CubicRealPolynomial_default.computeRealRoots(1, 1);
    }).toThrowDeveloperError();
  });
  it("real roots throws without d", function() {
    expect(function() {
      CubicRealPolynomial_default.computeRealRoots(1, 1, 1);
    }).toThrowDeveloperError();
  });
  it("three repeated roots", function() {
    const roots = CubicRealPolynomial_default.computeRealRoots(2, -12, 24, -16);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqualEpsilon(2, Math_default.EPSILON15);
    expect(roots[1]).toEqualEpsilon(2, Math_default.EPSILON15);
    expect(roots[2]).toEqualEpsilon(2, Math_default.EPSILON15);
  });
  it("one unique and two repeated roots", function() {
    const roots = CubicRealPolynomial_default.computeRealRoots(2, 2, -2, -2);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqualEpsilon(-1, Math_default.EPSILON15);
    expect(roots[1]).toEqualEpsilon(-1, Math_default.EPSILON15);
    expect(roots[2]).toEqualEpsilon(1, Math_default.EPSILON15);
  });
  it("three unique roots", function() {
    const roots = CubicRealPolynomial_default.computeRealRoots(2, 6, -26, -30);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqualEpsilon(-5, Math_default.EPSILON15);
    expect(roots[1]).toEqualEpsilon(-1, Math_default.EPSILON15);
    expect(roots[2]).toEqualEpsilon(3, Math_default.EPSILON15);
  });
  it("complex roots", function() {
    const roots = CubicRealPolynomial_default.computeRealRoots(2, -6, 10, -6);
    expect(roots.length).toEqual(1);
    expect(roots[0]).toEqualEpsilon(1, Math_default.EPSILON15);
  });
  it("quadratic case", function() {
    const roots = CubicRealPolynomial_default.computeRealRoots(0, 2, -4, -6);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(-1);
    expect(roots[1]).toEqual(3);
  });
  it("deflated case", function() {
    let roots = CubicRealPolynomial_default.computeRealRoots(1, 0, 1, 2);
    expect(roots.length).toEqual(1);
    expect(roots[0]).toEqualEpsilon(-1, Math_default.EPSILON14);
    roots = CubicRealPolynomial_default.computeRealRoots(1, 0, 0, -8);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqualEpsilon(2, Math_default.EPSILON14);
    roots = CubicRealPolynomial_default.computeRealRoots(1, 0, -1, 0);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqual(-1);
    expect(roots[1]).toEqual(0);
    expect(roots[2]).toEqual(1);
    roots = CubicRealPolynomial_default.computeRealRoots(1, 1, 0, 0);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqual(-1);
    expect(roots[1]).toEqual(0);
    expect(roots[2]).toEqual(0);
    roots = CubicRealPolynomial_default.computeRealRoots(1, -1, 0, 0);
    expect(roots.length).toEqual(3);
    expect(roots[0]).toEqual(0);
    expect(roots[1]).toEqual(0);
    expect(roots[2]).toEqual(1);
    roots = CubicRealPolynomial_default.computeRealRoots(1, 1, 1, 0);
    expect(roots.length).toEqual(1);
    expect(roots[0]).toEqual(0);
  });
});

// packages/core/Specs/CullingVolumeSpec.js
describe("Core/CullingVolume", function() {
  let cullingVolume;
  beforeEach(function() {
    const frustum = new PerspectiveFrustum_default();
    frustum.near = 1;
    frustum.far = 2;
    frustum.fov = Math.PI / 3;
    frustum.aspectRatio = 1;
    cullingVolume = frustum.computeCullingVolume(
      new Cartesian3_default(),
      Cartesian3_default.negate(Cartesian3_default.UNIT_Z, new Cartesian3_default()),
      Cartesian3_default.UNIT_Y
    );
  });
  it("computeVisibility throws without a bounding volume", function() {
    expect(function() {
      return new CullingVolume_default().computeVisibility();
    }).toThrowDeveloperError();
  });
  it("computeVisibilityWithPlaneMask throws without a bounding volume", function() {
    expect(function() {
      return new CullingVolume_default().computeVisibilityWithPlaneMask(
        void 0,
        CullingVolume_default.MASK_INDETERMINATE
      );
    }).toThrowDeveloperError();
  });
  it("computeVisibilityWithPlaneMask throws without a parent plane mask", function() {
    expect(function() {
      return new CullingVolume_default().computeVisibilityWithPlaneMask(
        new BoundingSphere_default(),
        void 0
      );
    }).toThrowDeveloperError();
  });
  function testWithAndWithoutPlaneMask(culling, bound, intersect) {
    expect(culling.computeVisibility(bound)).toEqual(intersect);
    const mask = culling.computeVisibilityWithPlaneMask(
      bound,
      CullingVolume_default.MASK_INDETERMINATE
    );
    if (intersect === Intersect_default.INSIDE) {
      expect(mask).toEqual(CullingVolume_default.MASK_INSIDE);
    } else if (intersect === Intersect_default.OUTSIDE) {
      expect(mask).toEqual(CullingVolume_default.MASK_OUTSIDE);
    } else {
      expect(mask).not.toEqual(CullingVolume_default.MASK_INSIDE);
      expect(mask).not.toEqual(CullingVolume_default.MASK_OUTSIDE);
    }
    expect(culling.computeVisibilityWithPlaneMask(bound, mask)).toEqual(mask);
  }
  describe("box intersections", function() {
    it("can contain an axis aligned bounding box", function() {
      const box1 = AxisAlignedBoundingBox_default.fromPoints([
        new Cartesian3_default(-0.5, 0, -1.25),
        new Cartesian3_default(0.5, 0, -1.25),
        new Cartesian3_default(-0.5, 0, -1.75),
        new Cartesian3_default(0.5, 0, -1.75)
      ]);
      testWithAndWithoutPlaneMask(cullingVolume, box1, Intersect_default.INSIDE);
    });
    describe("can partially contain an axis aligned bounding box", function() {
      it("on the far plane", function() {
        const box2 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 0, -1.5),
          new Cartesian3_default(0.5, 0, -1.5),
          new Cartesian3_default(-0.5, 0, -2.5),
          new Cartesian3_default(0.5, 0, -2.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box2,
          Intersect_default.INTERSECTING
        );
      });
      it("on the near plane", function() {
        const box3 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 0, -0.5),
          new Cartesian3_default(0.5, 0, -0.5),
          new Cartesian3_default(-0.5, 0, -1.5),
          new Cartesian3_default(0.5, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box3,
          Intersect_default.INTERSECTING
        );
      });
      it("on the left plane", function() {
        const box4 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-1.5, 0, -1.25),
          new Cartesian3_default(0, 0, -1.25),
          new Cartesian3_default(-1.5, 0, -1.5),
          new Cartesian3_default(0, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box4,
          Intersect_default.INTERSECTING
        );
      });
      it("on the right plane", function() {
        const box5 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(0, 0, -1.25),
          new Cartesian3_default(1.5, 0, -1.25),
          new Cartesian3_default(0, 0, -1.5),
          new Cartesian3_default(1.5, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box5,
          Intersect_default.INTERSECTING
        );
      });
      it("on the top plane", function() {
        const box6 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 0, -1.25),
          new Cartesian3_default(0.5, 0, -1.25),
          new Cartesian3_default(-0.5, 2, -1.75),
          new Cartesian3_default(0.5, 2, -1.75)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box6,
          Intersect_default.INTERSECTING
        );
      });
      it("on the bottom plane", function() {
        const box7 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, -2, -1.25),
          new Cartesian3_default(0.5, 0, -1.25),
          new Cartesian3_default(-0.5, -2, -1.5),
          new Cartesian3_default(0.5, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          box7,
          Intersect_default.INTERSECTING
        );
      });
    });
    describe("can not contain an axis aligned bounding box", function() {
      it("past the far plane", function() {
        const box8 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 0, -2.25),
          new Cartesian3_default(0.5, 0, -2.25),
          new Cartesian3_default(-0.5, 0, -2.75),
          new Cartesian3_default(0.5, 0, -2.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box8, Intersect_default.OUTSIDE);
      });
      it("before the near plane", function() {
        const box9 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 0, -0.25),
          new Cartesian3_default(0.5, 0, -0.25),
          new Cartesian3_default(-0.5, 0, -0.75),
          new Cartesian3_default(0.5, 0, -0.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box9, Intersect_default.OUTSIDE);
      });
      it("past the left plane", function() {
        const box10 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-5, 0, -1.25),
          new Cartesian3_default(-3, 0, -1.25),
          new Cartesian3_default(-5, 0, -1.75),
          new Cartesian3_default(-3, 0, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box10, Intersect_default.OUTSIDE);
      });
      it("past the right plane", function() {
        const box11 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(3, 0, -1.25),
          new Cartesian3_default(5, 0, -1.25),
          new Cartesian3_default(3, 0, -1.75),
          new Cartesian3_default(5, 0, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box11, Intersect_default.OUTSIDE);
      });
      it("past the top plane", function() {
        const box12 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, 3, -1.25),
          new Cartesian3_default(0.5, 3, -1.25),
          new Cartesian3_default(-0.5, 5, -1.75),
          new Cartesian3_default(0.5, 5, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box12, Intersect_default.OUTSIDE);
      });
      it("past the bottom plane", function() {
        const box13 = AxisAlignedBoundingBox_default.fromPoints([
          new Cartesian3_default(-0.5, -3, -1.25),
          new Cartesian3_default(0.5, -3, -1.25),
          new Cartesian3_default(-0.5, -5, -1.75),
          new Cartesian3_default(0.5, -5, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, box13, Intersect_default.OUTSIDE);
      });
    });
  });
  describe("sphere intersection", function() {
    it("can contain a sphere", function() {
      const sphere1 = BoundingSphere_default.fromPoints([
        new Cartesian3_default(0, 0, -1.25),
        new Cartesian3_default(0, 0, -1.75)
      ]);
      testWithAndWithoutPlaneMask(cullingVolume, sphere1, Intersect_default.INSIDE);
    });
    describe("can partially contain a sphere", function() {
      it("on the far plane", function() {
        const sphere2 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -1.5),
          new Cartesian3_default(0, 0, -2.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere2,
          Intersect_default.INTERSECTING
        );
      });
      it("on the near plane", function() {
        const sphere3 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -0.5),
          new Cartesian3_default(0, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere3,
          Intersect_default.INTERSECTING
        );
      });
      it("on the left plane", function() {
        const sphere4 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(-1, 0, -1.5),
          new Cartesian3_default(0, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere4,
          Intersect_default.INTERSECTING
        );
      });
      it("on the right plane", function() {
        const sphere5 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -1.5),
          new Cartesian3_default(1, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere5,
          Intersect_default.INTERSECTING
        );
      });
      it("on the top plane", function() {
        const sphere6 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -1.5),
          new Cartesian3_default(0, 2, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere6,
          Intersect_default.INTERSECTING
        );
      });
      it("on the bottom plane", function() {
        const sphere7 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, -2, -1.5),
          new Cartesian3_default(0, 0, -1.5)
        ]);
        testWithAndWithoutPlaneMask(
          cullingVolume,
          sphere7,
          Intersect_default.INTERSECTING
        );
      });
    });
    describe("can not contain a sphere", function() {
      it("past the far plane", function() {
        const sphere8 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -2.25),
          new Cartesian3_default(0, 0, -2.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere8, Intersect_default.OUTSIDE);
      });
      it("before the near plane", function() {
        const sphere9 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(0, 0, -0.25),
          new Cartesian3_default(0, 0, -0.5)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere9, Intersect_default.OUTSIDE);
      });
      it("past the left plane", function() {
        const sphere10 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(-5, 0, -1.25),
          new Cartesian3_default(-4.5, 0, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere10, Intersect_default.OUTSIDE);
      });
      it("past the right plane", function() {
        const sphere11 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(4.5, 0, -1.25),
          new Cartesian3_default(5, 0, -1.75)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere11, Intersect_default.OUTSIDE);
      });
      it("past the top plane", function() {
        const sphere12 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(-0.5, 4.5, -1.25),
          new Cartesian3_default(-0.5, 5, -1.25)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere12, Intersect_default.OUTSIDE);
      });
      it("past the bottom plane", function() {
        const sphere13 = BoundingSphere_default.fromPoints([
          new Cartesian3_default(-0.5, -4.5, -1.25),
          new Cartesian3_default(-0.5, -5, -1.25)
        ]);
        testWithAndWithoutPlaneMask(cullingVolume, sphere13, Intersect_default.OUTSIDE);
      });
    });
  });
  describe("construct from bounding sphere", function() {
    const boundingSphereCullingVolume = new BoundingSphere_default(
      new Cartesian3_default(1e3, 2e3, 3e3),
      100
    );
    const cullingVolume2 = CullingVolume_default.fromBoundingSphere(
      boundingSphereCullingVolume
    );
    it("throws without a boundingSphere", function() {
      expect(function() {
        CullingVolume_default.fromBoundingSphere(void 0);
      }).toThrowDeveloperError();
    });
    it("can contain a volume", function() {
      const sphere1 = BoundingSphere_default.clone(boundingSphereCullingVolume);
      sphere1.radius *= 0.5;
      testWithAndWithoutPlaneMask(cullingVolume2, sphere1, Intersect_default.INSIDE);
    });
    describe("can partially contain a volume", function() {
      it("on the far plane", function() {
        const offset = new Cartesian3_default(
          0,
          0,
          boundingSphereCullingVolume.radius * 1.5
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere2 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere2,
          Intersect_default.INTERSECTING
        );
      });
      it("on the near plane", function() {
        const offset = new Cartesian3_default(
          0,
          0,
          -boundingSphereCullingVolume.radius * 1.5
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere3 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere3,
          Intersect_default.INTERSECTING
        );
      });
      it("on the left plane", function() {
        const offset = new Cartesian3_default(
          -boundingSphereCullingVolume.radius * 1.5,
          0,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere4 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere4,
          Intersect_default.INTERSECTING
        );
      });
      it("on the right plane", function() {
        const offset = new Cartesian3_default(
          boundingSphereCullingVolume.radius * 1.5,
          0,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere5 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere5,
          Intersect_default.INTERSECTING
        );
      });
      it("on the top plane", function() {
        const offset = new Cartesian3_default(
          0,
          boundingSphereCullingVolume.radius * 1.5,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere6 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere6,
          Intersect_default.INTERSECTING
        );
      });
      it("on the bottom plane", function() {
        const offset = new Cartesian3_default(
          0,
          -boundingSphereCullingVolume.radius * 1.5,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere7 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(
          cullingVolume2,
          sphere7,
          Intersect_default.INTERSECTING
        );
      });
    });
    describe("can not contain a volume", function() {
      it("past the far plane", function() {
        const offset = new Cartesian3_default(
          0,
          0,
          boundingSphereCullingVolume.radius * 2
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere8 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere8, Intersect_default.OUTSIDE);
      });
      it("before the near plane", function() {
        const offset = new Cartesian3_default(
          0,
          0,
          -boundingSphereCullingVolume.radius * 2
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere9 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere9, Intersect_default.OUTSIDE);
      });
      it("past the left plane", function() {
        const offset = new Cartesian3_default(
          -boundingSphereCullingVolume.radius * 2,
          0,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere10 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere10, Intersect_default.OUTSIDE);
      });
      it("past the right plane", function() {
        const offset = new Cartesian3_default(
          boundingSphereCullingVolume.radius * 2,
          0,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere11 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere11, Intersect_default.OUTSIDE);
      });
      it("past the top plane", function() {
        const offset = new Cartesian3_default(
          0,
          boundingSphereCullingVolume.radius * 2,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere12 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere12, Intersect_default.OUTSIDE);
      });
      it("past the bottom plane", function() {
        const offset = new Cartesian3_default(
          0,
          -boundingSphereCullingVolume.radius * 2,
          0
        );
        const center = Cartesian3_default.add(
          boundingSphereCullingVolume.center,
          offset,
          new Cartesian3_default()
        );
        const radius = boundingSphereCullingVolume.radius * 0.5;
        const sphere13 = new BoundingSphere_default(center, radius);
        testWithAndWithoutPlaneMask(cullingVolume2, sphere13, Intersect_default.OUTSIDE);
      });
    });
  });
});

