// packages/core/Specs/deprecationWarningSpec.js
describe("Core/deprecationWarning", function() {
  it("logs a warning", function() {
    spyOn(console, "warn");
    deprecationWarning_default("deprecation-identifier", "message");
    deprecationWarning_default("deprecation-identifier", "message");
    deprecationWarning_default("another deprecation-identifier", "another message");
    expect(console.warn.calls.count()).toEqual(2);
    expect(console.warn.calls.argsFor(0)[0]).toBe("message");
    expect(console.warn.calls.argsFor(1)[0]).toBe("another message");
  });
  it("throws without identifier", function() {
    expect(function() {
      deprecationWarning_default();
    }).toThrowDeveloperError();
  });
  it("throws without message", function() {
    expect(function() {
      deprecationWarning_default("identifier");
    }).toThrowDeveloperError();
  });
});

// packages/core/Specs/DeveloperErrorSpec.js
describe("Core/DeveloperError", function() {
  const name = "DeveloperError";
  const testMessage = "Testing";
  let e;
  beforeEach(function() {
    e = new DeveloperError_default(testMessage);
  });
  it("has a name property", function() {
    expect(e.name).toEqual(name);
  });
  it("has a message property", function() {
    expect(e.message).toEqual(testMessage);
  });
  it("has a stack property", function() {
    if (!window.specsUsingRelease) {
      expect(e.stack).toContain(name);
    }
  });
  it("has a working toString", function() {
    const str = new DeveloperError_default(testMessage).toString();
    if (!window.specsUsingRelease) {
      expect(str).toContain(`${name}: ${testMessage}`);
    } else {
      expect(str).toContain(testMessage);
    }
  });
});

