// packages/core/Specs/DistanceDisplayConditionSpec.js
describe("Core/DistanceDisplayCondition", function() {
  it("default constructs", function() {
    const dc = new DistanceDisplayCondition_default();
    expect(dc.near).toEqual(0);
    expect(dc.far).toEqual(Number.MAX_VALUE);
  });
  it("constructs with parameters", function() {
    const near = 10;
    const far = 100;
    const dc = new DistanceDisplayCondition_default(near, far);
    expect(dc.near).toEqual(near);
    expect(dc.far).toEqual(far);
  });
  it("gets and sets properties", function() {
    const dc = new DistanceDisplayCondition_default();
    const near = 10;
    const far = 100;
    dc.near = near;
    dc.far = far;
    expect(dc.near).toEqual(near);
    expect(dc.far).toEqual(far);
  });
  it("determines equality with static function", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    expect(
      DistanceDisplayCondition_default.equals(
        dc,
        new DistanceDisplayCondition_default(10, 100)
      )
    ).toEqual(true);
    expect(
      DistanceDisplayCondition_default.equals(
        dc,
        new DistanceDisplayCondition_default(11, 100)
      )
    ).toEqual(false);
    expect(
      DistanceDisplayCondition_default.equals(
        dc,
        new DistanceDisplayCondition_default(10, 101)
      )
    ).toEqual(false);
    expect(DistanceDisplayCondition_default.equals(dc, void 0)).toEqual(false);
  });
  it("determines equality with prototype function", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    expect(dc.equals(new DistanceDisplayCondition_default(10, 100))).toEqual(true);
    expect(dc.equals(new DistanceDisplayCondition_default(11, 100))).toEqual(false);
    expect(dc.equals(new DistanceDisplayCondition_default(10, 101))).toEqual(false);
    expect(dc.equals(void 0)).toEqual(false);
  });
  it("static clones", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const result = DistanceDisplayCondition_default.clone(dc);
    expect(dc).toEqual(result);
  });
  it("static clone with a result parameter", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const result = new DistanceDisplayCondition_default();
    const returnedResult = DistanceDisplayCondition_default.clone(dc, result);
    expect(dc).not.toBe(result);
    expect(result).toBe(returnedResult);
    expect(dc).toEqual(result);
  });
  it("static clone works with a result parameter that is an input parameter", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const returnedResult = DistanceDisplayCondition_default.clone(dc, dc);
    expect(dc).toBe(returnedResult);
  });
  it("clones", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const result = dc.clone();
    expect(dc).toEqual(result);
  });
  it("clone with a result parameter", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const result = new DistanceDisplayCondition_default();
    const returnedResult = dc.clone(result);
    expect(dc).not.toBe(result);
    expect(result).toBe(returnedResult);
    expect(dc).toEqual(result);
  });
  it("clone works with a result parameter that is an input parameter", function() {
    const dc = new DistanceDisplayCondition_default(10, 100);
    const returnedResult = dc.clone(dc);
    expect(dc).toBe(returnedResult);
  });
  createPackableSpecs_default(
    DistanceDisplayCondition_default,
    new DistanceDisplayCondition_default(1, 2),
    [1, 2]
  );
});

