      semiMinorAxis: 1500,
      ellipsoid: Ellipsoid_default.WGS84,
      rotation: Math_default.PI_OVER_TWO,
      stRotation: Math_default.PI_OVER_FOUR,
      granularity: 1e4,
      extrudedHeight: 0,
      height: 100,
