    expect(sv._vertexFormat.bitangent).toBe(
      VertexFormat_default.POSITION_ONLY.bitangent
    );
    expect(sv._vertexFormat.color).toBe(VertexFormat_default.POSITION_ONLY.color);
    expect(sv._vertexFormat.normal).toBe(VertexFormat_default.POSITION_ONLY.normal);
    expect(sv._vertexFormat.position).toBe(VertexFormat_default.POSITION_ONLY.position);
    expect(sv._vertexFormat.st).toBe(VertexFormat_default.POSITION_ONLY.st);
