  it("normal use of localFrameToFixedFrameGenerator", function() {
    const cartesianTab = [
      new Cartesian3_default(0, 0, 1),
      new Cartesian3_default(0, 0, -1),
      new Cartesian3_default(10, 20, 30),
      new Cartesian3_default(-10, -20, -30),
      new Cartesian3_default(-25, 60, -1),
      new Cartesian3_default(9, 0, -7)
    ];
    const converterTab = [
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "north",
          "east"
        ),
        order: ["north", "east", "down"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "north",
          "west"
        ),
        order: ["north", "west", "up"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "north",
          "up"
        ),
        order: ["north", "up", "east"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "north",
          "down"
        ),
        order: ["north", "down", "west"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "south",
          "east"
        ),
        order: ["south", "east", "up"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "south",
          "west"
        ),
        order: ["south", "west", "down"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "south",
          "up"
        ),
        order: ["south", "up", "west"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "south",
          "down"
        ),
        order: ["south", "down", "east"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "east",
          "north"
        ),
        order: ["east", "north", "up"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "east",
          "south"
        ),
        order: ["east", "south", "down"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "east",
          "up"
        ),
        order: ["east", "up", "south"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "east",
          "down"
        ),
        order: ["east", "down", "north"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "west",
          "north"
        ),
        order: ["west", "north", "down"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "west",
          "south"
        ),
        order: ["west", "south", "up"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "west",
          "up"
        ),
        order: ["west", "up", "north"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "west",
          "down"
        ),
        order: ["west", "down", "south"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "up",
          "north"
        ),
        order: ["up", "north", "west"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "up",
          "south"
        ),
        order: ["up", "south", "east"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "up",
          "east"
        ),
        order: ["up", "east", "north"]
      },
      {
        converter: FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          "up",
          "west"
        ),
        order: ["up", "west", "south"]
      }
    ];
    function testAllLocalFrame(classicalENUMatrix, position) {
      const ENUColumn = new Cartesian4_default();
      const converterColumn = new Cartesian4_default();
      for (let i = 0; i < converterTab.length; i++) {
        const converterMatrix = converterTab[i].converter(
          position,
          Ellipsoid_default.UNIT_SPHERE
        );
        const order = converterTab[i].order;
        Matrix4_default.getColumn(classicalENUMatrix, 3, ENUColumn);
        Matrix4_default.getColumn(converterMatrix, 3, converterColumn);
        expect(ENUColumn).toEqual(converterColumn);
        for (let j = 0; j < 3; j++) {
          Matrix4_default.getColumn(converterMatrix, j, converterColumn);
          const axisName = order[j];
          if (axisName === "east") {
            Matrix4_default.getColumn(classicalENUMatrix, 0, ENUColumn);
          } else if (axisName === "west") {
            Matrix4_default.getColumn(classicalENUMatrix, 0, ENUColumn);
            Cartesian4_default.negate(ENUColumn, ENUColumn);
          } else if (axisName === "north") {
            Matrix4_default.getColumn(classicalENUMatrix, 1, ENUColumn);
          } else if (axisName === "south") {
            Matrix4_default.getColumn(classicalENUMatrix, 1, ENUColumn);
            Cartesian4_default.negate(ENUColumn, ENUColumn);
          } else if (axisName === "up") {
            Matrix4_default.getColumn(classicalENUMatrix, 2, ENUColumn);
          } else if (axisName === "down") {
            Matrix4_default.getColumn(classicalENUMatrix, 2, ENUColumn);
            Cartesian4_default.negate(ENUColumn, ENUColumn);
          }
          expect(ENUColumn).toEqual(converterColumn);
        }
      }
    }
    for (let i = 0; i < cartesianTab.length; i++) {
      const cartesian11 = cartesianTab[i];
      const classicalEastNorthUpReferential = FixedFrameTransforms_default.eastNorthUpToFixedFrame(
        cartesian11,
        Ellipsoid_default.UNIT_SPHERE
      );
      testAllLocalFrame(classicalEastNorthUpReferential, cartesian11);
    }
  });
  it("abnormal use of localFrameToFixedFrameGenerator", function() {
    function checkDeveloperError(firstAxis, secondAxis) {
      expect(function() {
        FixedFrameTransforms_default.localFrameToFixedFrameGenerator(
          firstAxis,
          secondAxis
        );
      }).toThrowDeveloperError();
    }
    checkDeveloperError(void 0, void 0);
    checkDeveloperError("north", void 0);
    checkDeveloperError(void 0, "north");
    checkDeveloperError("south", void 0);
    checkDeveloperError("northe", "southe");
    checkDeveloperError("north", "north");
    checkDeveloperError("north", "south");
    checkDeveloperError("south", "north");
    checkDeveloperError("south", "south");
    checkDeveloperError("up", "up");
    checkDeveloperError("up", "down");
    checkDeveloperError("down", "up");
    checkDeveloperError("down", "down");
    checkDeveloperError("east", "east");
    checkDeveloperError("east", "west");
    checkDeveloperError("west", "east");
    checkDeveloperError("west", "west");
  });
  it("headingPitchRollToFixedFrame works without a result parameter", function() {
    const origin = new Cartesian3_default(1, 0, 0);
    const heading = Math_default.toRadians(20);
    const pitch = Math_default.toRadians(30);
    const roll = Math_default.toRadians(40);
    const hpr = new HeadingPitchRoll_default(heading, pitch, roll);
    const expectedRotation = Matrix3_default.fromQuaternion(
      Quaternion_default.fromHeadingPitchRoll(hpr)
    );
    const expectedX = Matrix3_default.getColumn(expectedRotation, 0, new Cartesian3_default());
    const expectedY = Matrix3_default.getColumn(expectedRotation, 1, new Cartesian3_default());
    const expectedZ = Matrix3_default.getColumn(expectedRotation, 2, new Cartesian3_default());
    Cartesian3_default.fromElements(expectedX.z, expectedX.x, expectedX.y, expectedX);
    Cartesian3_default.fromElements(expectedY.z, expectedY.x, expectedY.y, expectedY);
    Cartesian3_default.fromElements(expectedZ.z, expectedZ.x, expectedZ.y, expectedZ);
    const returnedResult = FixedFrameTransforms_default.headingPitchRollToFixedFrame(
      origin,
      hpr,
      Ellipsoid_default.UNIT_SPHERE
    );
    const actualX = Cartesian3_default.fromCartesian4(
      Matrix4_default.getColumn(returnedResult, 0, new Cartesian4_default())
    );
    const actualY = Cartesian3_default.fromCartesian4(
      Matrix4_default.getColumn(returnedResult, 1, new Cartesian4_default())
    );
    const actualZ = Cartesian3_default.fromCartesian4(
      Matrix4_default.getColumn(returnedResult, 2, new Cartesian4_default())
    );
    const actualTranslation = Cartesian3_default.fromCartesian4(
      Matrix4_default.getColumn(returnedResult, 3, new Cartesian4_default())
    );
    expect(actualX).toEqual(expectedX);
    expect(actualY).toEqual(expectedY);
    expect(actualZ).toEqual(expectedZ);
    expect(actualTranslation).toEqual(origin);
  });
