  it("basisTo2D projects translation", function() {
    const ellipsoid = Ellipsoid_default.WGS84;
    const projection = new GeographicProjection_default(ellipsoid);
    const origin = Cartesian3_default.fromDegrees(-72, 40, 100, ellipsoid);
    const heading = Math_default.toRadians(90);
    const pitch = Math_default.toRadians(45);
    const roll = 0;
    const hpr = new HeadingPitchRoll_default(heading, pitch, roll);
    const modelMatrix = FixedFrameTransforms_default.headingPitchRollToFixedFrame(
      origin,
      hpr,
      ellipsoid
    );
    const modelMatrix2D = FixedFrameTransforms_default.basisTo2D(
      projection,
      modelMatrix,
      new Matrix4_default()
    );
    const translation2D = Cartesian3_default.fromCartesian4(
      Matrix4_default.getColumn(modelMatrix2D, 3, new Cartesian4_default())
    );
    const carto = ellipsoid.cartesianToCartographic(origin);
    const expected = projection.project(carto);
    Cartesian3_default.fromElements(expected.z, expected.x, expected.y, expected);
    expect(translation2D).toEqual(expected);
  });
  it("basisTo2D transforms rotation", function() {
    const ellipsoid = Ellipsoid_default.WGS84;
    const projection = new GeographicProjection_default(ellipsoid);
    const origin = Cartesian3_default.fromDegrees(-72, 40, 100, ellipsoid);
    const heading = Math_default.toRadians(90);
    const pitch = Math_default.toRadians(45);
    const roll = 0;
    const hpr = new HeadingPitchRoll_default(heading, pitch, roll);
    const modelMatrix = FixedFrameTransforms_default.headingPitchRollToFixedFrame(
      origin,
      hpr,
      ellipsoid
    );
    const modelMatrix2D = FixedFrameTransforms_default.basisTo2D(
      projection,
      modelMatrix,
      new Matrix4_default()
    );
    const rotation2D = Matrix4_default.getMatrix3(modelMatrix2D, new Matrix3_default());
    const enu = FixedFrameTransforms_default.eastNorthUpToFixedFrame(origin, ellipsoid);
    const enuInverse = Matrix4_default.inverseTransformation(enu, enu);
    const hprPlusTranslate = Matrix4_default.multiply(
      enuInverse,
      modelMatrix,
      new Matrix4_default()
    );
    const hpr2 = Matrix4_default.getMatrix3(hprPlusTranslate, new Matrix3_default());
    const row0 = Matrix3_default.getRow(hpr2, 0, new Cartesian3_default());
    const row1 = Matrix3_default.getRow(hpr2, 1, new Cartesian3_default());
    const row2 = Matrix3_default.getRow(hpr2, 2, new Cartesian3_default());
    const expected = new Matrix3_default();
    Matrix3_default.setRow(expected, 0, row2, expected);
    Matrix3_default.setRow(expected, 1, row0, expected);
    Matrix3_default.setRow(expected, 2, row1, expected);
    expect(rotation2D).toEqualEpsilon(expected, Math_default.EPSILON3);
  });
