// packages/core/Specs/GeographicProjectionSpec.js
describe("Core/GeographicProjection", function() {
  it("construct0", function() {
    const projection = new GeographicProjection_default();
    expect(projection.ellipsoid).toEqual(Ellipsoid_default.WGS84);
  });
  it("construct1", function() {
    const ellipsoid = Ellipsoid_default.UNIT_SPHERE;
    const projection = new GeographicProjection_default(ellipsoid);
    expect(projection.ellipsoid).toEqual(ellipsoid);
  });
  it("project0", function() {
    const height = 10;
    const cartographic2 = new Cartographic_default(0, 0, height);
    const projection = new GeographicProjection_default();
    expect(projection.project(cartographic2)).toEqual(
      new Cartesian3_default(0, 0, height)
    );
  });
  it("project1", function() {
    const ellipsoid = Ellipsoid_default.WGS84;
    const cartographic2 = new Cartographic_default(Math.PI, Math_default.PI_OVER_TWO, 0);
    const expected = new Cartesian3_default(
      Math.PI * ellipsoid.radii.x,
      Math_default.PI_OVER_TWO * ellipsoid.radii.x,
      0
    );
    const projection = new GeographicProjection_default(ellipsoid);
    expect(projection.project(cartographic2)).toEqual(expected);
  });
  it("project2", function() {
    const ellipsoid = Ellipsoid_default.UNIT_SPHERE;
    const cartographic2 = new Cartographic_default(
      -Math.PI,
      Math_default.PI_OVER_TWO,
      0
    );
    const expected = new Cartesian3_default(-Math.PI, Math_default.PI_OVER_TWO, 0);
    const projection = new GeographicProjection_default(ellipsoid);
    expect(projection.project(cartographic2)).toEqual(expected);
  });
  it("project3", function() {
    const ellipsoid = Ellipsoid_default.WGS84;
    const cartographic2 = new Cartographic_default(Math.PI, Math_default.PI_OVER_TWO, 0);
    const expected = new Cartesian3_default(
      Math.PI * ellipsoid.radii.x,
      Math_default.PI_OVER_TWO * ellipsoid.radii.x,
      0
    );
    const projection = new GeographicProjection_default(ellipsoid);
    const result = new Cartesian3_default(0, 0, 0);
    const returnValue = projection.project(cartographic2, result);
    expect(result).toEqual(returnValue);
    expect(result).toEqual(expected);
  });
  it("unproject0", function() {
    const cartographic2 = new Cartographic_default(
      Math_default.PI_OVER_TWO,
      Math_default.PI_OVER_FOUR,
      12
    );
    const projection = new GeographicProjection_default();
    const projected = projection.project(cartographic2);
    expect(projection.unproject(projected)).toEqual(cartographic2);
  });
  it("unproject1", function() {
    const cartographic2 = new Cartographic_default(
      Math_default.PI_OVER_TWO,
      Math_default.PI_OVER_FOUR,
      12
    );
    const projection = new GeographicProjection_default();
    const projected = projection.project(cartographic2);
    const result = new Cartographic_default(0, 0, 0);
    const returnValue = projection.unproject(projected, result);
    expect(result).toEqual(returnValue);
    expect(result).toEqual(cartographic2);
  });
  it("project throws without cartesian", function() {
    const projection = new GeographicProjection_default();
    expect(function() {
      return projection.unproject();
    }).toThrowDeveloperError();
  });
});

