// packages/core/Specs/GeometryInstanceSpec.js
describe("Core/GeometryInstance", function() {
  it("constructor", function() {
    const geometry = new Geometry_default({
      attributes: {
        position: new GeometryAttribute_default({
          componentDatatype: ComponentDatatype_default.DOUBLE,
          componentsPerAttribute: 3,
          values: new Float64Array([
            0,
            0,
            0,
            1,
            0,
            0,
            0,
            1,
            0
          ])
        })
      },
      indices: new Uint16Array([0, 1, 2]),
      primitiveType: PrimitiveType_default.TRIANGLES,
      boundingSphere: new BoundingSphere_default(new Cartesian3_default(0.5, 0.5, 0), 1)
    });
    const modelMatrix = Matrix4_default.multiplyByTranslation(
      Matrix4_default.IDENTITY,
      new Cartesian3_default(0, 0, 9e6),
      new Matrix4_default()
    );
    const attributes = {
      color: new GeometryInstanceAttribute_default({
        componentDatatype: ComponentDatatype_default.UNSIGNED_BYTE,
        componentsPerAttribute: 4,
        normalize: true,
        value: new Uint8Array([255, 255, 0, 255])
      })
    };
    const instance = new GeometryInstance_default({
      geometry,
      modelMatrix,
      id: "geometry",
      attributes
    });
    expect(instance.geometry).toBe(geometry);
    expect(instance.modelMatrix).toEqual(modelMatrix);
    expect(instance.id).toEqual("geometry");
    expect(attributes).toBe(attributes);
  });
  it("constructor throws without geometry", function() {
    expect(function() {
      return new GeometryInstance_default();
    }).toThrowDeveloperError();
  });
});

