// packages/core/Specs/GeometrySpec.js
describe("Core/Geometry", function() {
  it("constructor", function() {
    const attributes = {
      position: new GeometryAttribute_default({
        componentDatatype: ComponentDatatype_default.DOUBLE,
        componentsPerAttribute: 3,
        values: new Float64Array([0, 0, 0, 1, 0, 0, 0, 1, 0])
      })
    };
    const indices = new Uint16Array([0, 1, 2]);
    const boundingSphere = new BoundingSphere_default(
      new Cartesian3_default(0.5, 0.5, 0),
      1
    );
    const geometry = new Geometry_default({
      attributes,
      indices,
      primitiveType: PrimitiveType_default.TRIANGLES,
      boundingSphere,
      geometryType: GeometryType_default.TRIANGLES
    });
    expect(geometry.attributes).toBe(attributes);
    expect(geometry.indices).toBe(indices);
    expect(geometry.primitiveType).toEqual(PrimitiveType_default.TRIANGLES);
    expect(geometry.boundingSphere).toBe(boundingSphere);
    expect(geometry.geometryType).toEqual(GeometryType_default.TRIANGLES);
  });
  it("constructor throws without attributes", function() {
    expect(function() {
      return new Geometry_default({
        primitiveType: PrimitiveType_default.TRIANGLES
      });
    }).toThrowDeveloperError();
  });
  it("computeNumberOfVertices", function() {
    const attributes = {
      position: new GeometryAttribute_default({
        componentDatatype: ComponentDatatype_default.DOUBLE,
        componentsPerAttribute: 3,
        values: new Float64Array([0, 0, 0, 1, 0, 0, 0, 1, 0])
      }),
      st: new GeometryAttribute_default({
        componentDatatype: ComponentDatatype_default.FLOAT,
        componentsPerAttribute: 2,
        values: new Float32Array([0, 0, 1, 0, 0, 1])
      })
    };
    const indices = new Uint16Array([0, 1, 2]);
    const boundingSphere = new BoundingSphere_default(
      new Cartesian3_default(0.5, 0.5, 0),
      1
    );
    const geometry = new Geometry_default({
      attributes,
      indices,
      primitiveType: PrimitiveType_default.TRIANGLES,
      boundingSphere
    });
    expect(Geometry_default.computeNumberOfVertices(geometry)).toEqual(3);
  });
  it("computeNumberOfVertices throws when attributes have different number of vertices", function() {
    const attributes = {
      position: new GeometryAttribute_default({
        componentDatatype: ComponentDatatype_default.DOUBLE,
        componentsPerAttribute: 3,
        values: new Float64Array([0, 0, 0, 1, 0, 0, 0, 1, 0])
      }),
      st: new GeometryAttribute_default({
        componentDatatype: ComponentDatatype_default.FLOAT,
        componentsPerAttribute: 2,
        values: new Float32Array([0, 0, 1, 0])
      })
    };
    const indices = new Uint16Array([0, 1, 2]);
    const boundingSphere = new BoundingSphere_default(
      new Cartesian3_default(0.5, 0.5, 0),
      1
    );
    const geometry = new Geometry_default({
      attributes,
      indices,
      primitiveType: PrimitiveType_default.TRIANGLES,
      boundingSphere
    });
    expect(function() {
      Geometry_default.computeNumberOfVertices(geometry);
    }).toThrowDeveloperError();
  });
  it("computeNumberOfVertices throws without geometry", function() {
    expect(function() {
      Geometry_default.computeNumberOfVertices();
    }).toThrowDeveloperError();
  });
  it("computes textureCoordinateRotationPoints for collections of points", function() {
    const positions = Cartesian3_default.fromDegreesArrayHeights([
      -10,
      -10,
      0,
      -10,
      10,
      0,
      10,
      -10,
      0,
      10,
      10,
      0
    ]);
    const boundingRectangle = Rectangle_default.fromCartesianArray(positions);
    const textureCoordinateRotationPoints4 = Geometry_default._textureCoordinateRotationPoints(
      positions,
      0,
      Ellipsoid_default.WGS84,
      boundingRectangle
    );
    expect(textureCoordinateRotationPoints4.length).toEqual(6);
    expect(textureCoordinateRotationPoints4[0]).toEqualEpsilon(
      0,
      Math_default.EPSILON7
    );
    expect(textureCoordinateRotationPoints4[1]).toEqualEpsilon(
      0,
      Math_default.EPSILON7
    );
    expect(textureCoordinateRotationPoints4[2]).toEqualEpsilon(
      0,
      Math_default.EPSILON7
    );
    expect(textureCoordinateRotationPoints4[3]).toEqualEpsilon(
      1,
      Math_default.EPSILON7
    );
    expect(textureCoordinateRotationPoints4[4]).toEqualEpsilon(
      1,
      Math_default.EPSILON7
    );
    expect(textureCoordinateRotationPoints4[5]).toEqualEpsilon(
      0,
      Math_default.EPSILON7
    );
  });
});

// packages/core/Specs/getAbsoluteUriSpec.js
describe("Core/getAbsoluteUri", function() {
  it("works as expected", function() {
    let result = getAbsoluteUri_default(
      "http://www.mysite.com/awesome?makeitawesome=true"
    );
    expect(result).toEqual("http://www.mysite.com/awesome?makeitawesome=true");
    result = getAbsoluteUri_default("awesome.png", "http://test.com");
    expect(result).toEqual("http://test.com/awesome.png");
    result = getAbsoluteUri_default("awesome.png");
    expect(result).toEqual(`${getBaseUri_default(document.location.href)}awesome.png`);
  });
  it("document.baseURI is respected", function() {
    const fakeDocument = {
      baseURI: "http://test.com/index.html",
      location: document.location
    };
    const result = getAbsoluteUri_default._implementation(
      "awesome.png",
      void 0,
      fakeDocument
    );
    expect(result).toEqual("http://test.com/awesome.png");
  });
  it("throws with undefined parameter", function() {
    expect(function() {
      getAbsoluteUri_default(void 0);
    }).toThrowDeveloperError();
  });
});

// packages/core/Specs/getBaseUriSpec.js
describe("Core/getBaseUri", function() {
  it("works as expected", function() {
    let result = getBaseUri_default("http://www.mysite.com/awesome?makeitawesome=true");
    expect(result).toEqual("http://www.mysite.com/");
    result = getBaseUri_default(
      "http://www.mysite.com/somefolder/awesome.png#makeitawesome"
    );
    expect(result).toEqual("http://www.mysite.com/somefolder/");
  });
  it("works with includeQuery flag", function() {
    let result = getBaseUri_default(
      "http://www.mysite.com/awesome?makeitawesome=true",
      true
    );
    expect(result).toEqual("http://www.mysite.com/?makeitawesome=true");
    result = getBaseUri_default(
      "http://www.mysite.com/somefolder/awesome.png#makeitawesome",
      true
    );
    expect(result).toEqual("http://www.mysite.com/somefolder/#makeitawesome");
  });
  it("throws with undefined parameter", function() {
    expect(function() {
      getBaseUri_default(void 0);
    }).toThrowDeveloperError();
  });
});

