// packages/core/Specs/LagrangePolynomialApproximationSpec.js
describe("Core/LagrangePolynomialApproximation", function() {
  const xTable = [0, 60, 120, 180, 240, 300, 360, 420];
  const yTable = [
    13378137,
    0,
    0,
    133741283576279e-7,
    327475.593690065,
    0,
    133621048328212e-7,
    654754.936954423,
    0,
    133420736310691e-7,
    981641.896976832,
    0,
    133140467567223e-7,
    130794057608951e-8,
    0,
    13278041005799e-6,
    163345542917117e-8,
    0,
    132340779559193e-7,
    195799138083385e-8,
    0,
    13182183953374e-6,
    228135394232816e-8,
    0
  ];
  const x = 100;
  it("interpolation produces correct results.", function() {
    const result = LagrangePolynomialApproximation_default.interpolateOrderZero(
      x,
      xTable,
      yTable,
      3
    );
    const expectedResult = [13367002870928623e-9, 545695.7388100647, 0];
    expect(result).toEqualEpsilon(expectedResult, 1e-15);
  });
  it("interpolation produces correct results with a result parameter", function() {
    const result = new Array(3);
    const returnedResult = LagrangePolynomialApproximation_default.interpolateOrderZero(
      x,
      xTable,
      yTable,
      3,
      result
    );
    const expectedResult = [13367002870928623e-9, 545695.7388100647, 0];
    expect(result).toBe(returnedResult);
    expect(result).toEqualEpsilon(expectedResult, 1e-15);
  });
  it("getRequiredDataPoints should be 1 more than degree, except for 0, which requires 2", function() {
    expect(LagrangePolynomialApproximation_default.getRequiredDataPoints(0)).toEqual(2);
    expect(LagrangePolynomialApproximation_default.getRequiredDataPoints(1)).toEqual(2);
    expect(LagrangePolynomialApproximation_default.getRequiredDataPoints(2)).toEqual(3);
    expect(LagrangePolynomialApproximation_default.getRequiredDataPoints(3)).toEqual(4);
  });
});

