// packages/core/Specs/LinearApproximationSpec.js
describe("Core/LinearApproximation", function() {
  it("should produce correct results", function() {
    const xTable = [2, 4];
    const yTable = [2, 3, 4, 34];
    const results = LinearApproximation_default.interpolateOrderZero(
      3,
      xTable,
      yTable,
      2
    );
    expect(results.length).toEqual(2);
    expect(results[0]).toEqual(3);
    expect(results[1]).toEqual(18.5);
  });
  it("should produce correct results with a result parameter", function() {
    const xTable = [2, 4];
    const yTable = [2, 3, 4, 34];
    const result = new Array(2);
    const results = LinearApproximation_default.interpolateOrderZero(
      3,
      xTable,
      yTable,
      2,
      result
    );
    expect(result).toBe(results);
    expect(results.length).toEqual(2);
    expect(results[0]).toEqual(3);
    expect(results[1]).toEqual(18.5);
  });
  it("should produce correct results 2", function() {
    const xTable2 = [40, 120];
    const yTable2 = [20, 40, 60, 80, 90, 100];
    const results = LinearApproximation_default.interpolateOrderZero(
      80,
      xTable2,
      yTable2,
      3
    );
    expect(results.length).toEqual(3);
    expect(results[0]).toEqual(50);
    expect(results[1]).toEqual(65);
    expect(results[2]).toEqual(80);
  });
  it("should produce correct results 3", function() {
    const xTable3 = [20, 30];
    const yTable3 = [10, 20, 30, 20, 30, 40, 20, 40, 60, 80, 90, 100];
    const results = LinearApproximation_default.interpolateOrderZero(
      40,
      xTable3,
      yTable3,
      1
    );
    expect(results.length).toEqual(1);
    expect(results[0]).toEqual(30);
  });
  it("should throw if length is greater than 2", function() {
    const xTable = [44, 99, 230];
    const yTable = [2.3, 4.5, 6.6, 3.2, 4.4, 12.23];
    expect(function() {
      LinearApproximation_default.interpolateOrderZero(2.3, xTable, yTable, 3);
    }).toThrowDeveloperError();
  });
  it("should throw when yStride equals zero indicating that there are no dependent variables for interpolation", function() {
    const xTable = [4, 8];
    const yTable = [4, 8];
    expect(function() {
      LinearApproximation_default.interpolateOrderZero(6, xTable, yTable, 0);
    }).toThrowDeveloperError();
  });
  it("getRequiredDataPoints returns 2", function() {
    expect(LinearApproximation_default.getRequiredDataPoints(1)).toEqual(2);
  });
});

