  it("fromTransformation works with a result parameter", function() {
    const translation2 = new Cartesian3_default(1, 2, 3);
    const rotation = Quaternion_default.fromAxisAngle(Cartesian3_default.UNIT_Z, 0.4);
    const scale = new Cartesian3_default(1, 2, 3);
    const transformation = Matrix4_default.fromTranslationQuaternionRotationScale(
      translation2,
      rotation,
      scale
    );
    const box = new OrientedBoundingBox_default();
    OrientedBoundingBox_default.fromTransformation(transformation, box);
    expect(box.center).toEqual(translation2);
    expect(box.halfAxes).toEqualEpsilon(
      Matrix3_default.multiplyByUniformScale(
        Matrix4_default.getMatrix3(transformation, new Matrix3_default()),
        0.5,
        new Matrix3_default()
      ),
      Math_default.EPSILON14
    );
  });
