  it("distanceSquaredTo", function() {
    const r0 = Matrix3_default.fromRotationZ(Math_default.toRadians(-45));
    const r1 = Matrix3_default.fromRotationY(Math_default.toRadians(45));
    const rotation = Matrix3_default.multiply(r1, r0, r0);
    const scale = new Cartesian3_default(2, 3, 4);
    const rotationScale = Matrix3_default.multiplyByScale(
      rotation,
      scale,
      new Matrix3_default()
    );
    const center = new Cartesian3_default(4, 3, 2);
    const obb = new OrientedBoundingBox_default(center, rotationScale);
    const halfAxes = obb.halfAxes;
    const xAxis = Matrix3_default.getColumn(halfAxes, 0, new Cartesian3_default());
    const yAxis = Matrix3_default.getColumn(halfAxes, 1, new Cartesian3_default());
    const zAxis = Matrix3_default.getColumn(halfAxes, 2, new Cartesian3_default());
    const cartesian11 = Cartesian3_default.multiplyByScalar(xAxis, 2, new Cartesian3_default());
    Cartesian3_default.add(cartesian11, center, cartesian11);
    let d = Cartesian3_default.distance(cartesian11, center) - scale.x;
    let expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.multiplyByScalar(xAxis, -2, cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - scale.x;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.multiplyByScalar(yAxis, 2, cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - scale.y;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.multiplyByScalar(yAxis, -2, cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - scale.y;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.multiplyByScalar(zAxis, 2, cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - scale.z;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.multiplyByScalar(zAxis, -2, cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - scale.z;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    Cartesian3_default.add(xAxis, yAxis, cartesian11);
    Cartesian3_default.add(zAxis, cartesian11, cartesian11);
    const cornerDistance = Cartesian3_default.magnitude(cartesian11);
    Cartesian3_default.add(cartesian11, center, cartesian11);
    d = Cartesian3_default.distance(cartesian11, center) - cornerDistance;
    expected = d * d;
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      expected,
      Math_default.EPSILON10
    );
    const offset = Cartesian3_default.multiplyByScalar(scale, 0.25, new Cartesian3_default());
    Matrix3_default.multiplyByVector(rotation, offset, offset);
    Cartesian3_default.add(center, offset, cartesian11);
    expect(obb.distanceSquaredTo(cartesian11)).toEqualEpsilon(
      0,
      Math_default.EPSILON10
    );
  });
