  it("computePlaneDistances", function() {
    const r0 = Matrix3_default.fromRotationZ(Math_default.toRadians(-45));
    const r1 = Matrix3_default.fromRotationY(Math_default.toRadians(45));
    const rotation = Matrix3_default.multiply(r1, r0, r0);
    const scale = new Cartesian3_default(2, 3, 4);
    const rotationScale = Matrix3_default.multiplyByScale(rotation, scale, rotation);
    const center = new Cartesian3_default(4, 3, 2);
    const obb = new OrientedBoundingBox_default(center, rotationScale);
    const halfAxes = obb.halfAxes;
    const xAxis = Matrix3_default.getColumn(halfAxes, 0, new Cartesian3_default());
    const yAxis = Matrix3_default.getColumn(halfAxes, 1, new Cartesian3_default());
    const zAxis = Matrix3_default.getColumn(halfAxes, 2, new Cartesian3_default());
    const position = Cartesian3_default.multiplyByScalar(xAxis, 2, new Cartesian3_default());
    Cartesian3_default.add(position, center, position);
    const direction = Cartesian3_default.negate(xAxis, new Cartesian3_default());
    Cartesian3_default.normalize(direction, direction);
    let d = Cartesian3_default.distance(position, center);
    let expectedNear = d - scale.x;
    let expectedFar = d + scale.x;
    const distances = obb.computePlaneDistances(position, direction);
    expect(distances.start).toEqualEpsilon(expectedNear, Math_default.EPSILON14);
    expect(distances.stop).toEqualEpsilon(expectedFar, Math_default.EPSILON14);
    Cartesian3_default.multiplyByScalar(yAxis, 2, position);
    Cartesian3_default.add(position, center, position);
    Cartesian3_default.negate(yAxis, direction);
    Cartesian3_default.normalize(direction, direction);
    d = Cartesian3_default.distance(position, center);
    expectedNear = d - scale.y;
    expectedFar = d + scale.y;
    obb.computePlaneDistances(position, direction, distances);
    expect(distances.start).toEqualEpsilon(expectedNear, Math_default.EPSILON14);
    expect(distances.stop).toEqualEpsilon(expectedFar, Math_default.EPSILON14);
    Cartesian3_default.multiplyByScalar(zAxis, 2, position);
    Cartesian3_default.add(position, center, position);
    Cartesian3_default.negate(zAxis, direction);
    Cartesian3_default.normalize(direction, direction);
    d = Cartesian3_default.distance(position, center);
    expectedNear = d - scale.z;
    expectedFar = d + scale.z;
    obb.computePlaneDistances(position, direction, distances);
    expect(distances.start).toEqualEpsilon(expectedNear, Math_default.EPSILON14);
    expect(distances.stop).toEqualEpsilon(expectedFar, Math_default.EPSILON14);
    Cartesian3_default.add(xAxis, yAxis, position);
    Cartesian3_default.add(zAxis, position, position);
    Cartesian3_default.negate(position, direction);
    Cartesian3_default.normalize(direction, direction);
    const cornerDistance = Cartesian3_default.magnitude(position);
    Cartesian3_default.add(position, center, position);
    d = Cartesian3_default.distance(position, center);
    expectedNear = d - cornerDistance;
    expectedFar = d + cornerDistance;
    obb.computePlaneDistances(position, direction, distances);
    expect(distances.start).toEqualEpsilon(expectedNear, Math_default.EPSILON14);
    expect(distances.stop).toEqualEpsilon(expectedFar, Math_default.EPSILON14);
  });
