// packages/core/Specs/PrimitiveTypeSpec.js
describe("Core/PrimitiveType", function() {
  it("validate works", function() {
    expect(PrimitiveType_default.validate(PrimitiveType_default.POINTS)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.LINES)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.LINE_LOOP)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.LINE_STRIP)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.TRIANGLES)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.TRIANGLE_STRIP)).toBe(true);
    expect(PrimitiveType_default.validate(PrimitiveType_default.TRIANGLE_FAN)).toBe(true);
    expect(PrimitiveType_default.validate(void 0)).toBe(false);
  });
  it("isLines works", function() {
    expect(PrimitiveType_default.isLines(PrimitiveType_default.POINTS)).toBe(false);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.LINES)).toBe(true);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.LINE_LOOP)).toBe(true);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.LINE_STRIP)).toBe(true);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.TRIANGLES)).toBe(false);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.TRIANGLE_STRIP)).toBe(false);
    expect(PrimitiveType_default.isLines(PrimitiveType_default.TRIANGLE_FAN)).toBe(false);
    expect(PrimitiveType_default.isLines(void 0)).toBe(false);
  });
  it("isTriangles works", function() {
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.POINTS)).toBe(false);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.LINES)).toBe(false);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.LINE_LOOP)).toBe(false);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.LINE_STRIP)).toBe(false);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.TRIANGLES)).toBe(true);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.TRIANGLE_STRIP)).toBe(true);
    expect(PrimitiveType_default.isTriangles(PrimitiveType_default.TRIANGLE_FAN)).toBe(true);
    expect(PrimitiveType_default.isTriangles(void 0)).toBe(false);
  });
});

// packages/core/Specs/QuadraticRealPolynomialSpec.js
describe("Core/QuadraticRealPolynomial", function() {
  it("discriminant throws without a", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeDiscriminant();
    }).toThrowDeveloperError();
  });
  it("discriminant throws without b", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeDiscriminant(1);
    }).toThrowDeveloperError();
  });
  it("discriminant throws without c", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeDiscriminant(1, 1);
    }).toThrowDeveloperError();
  });
  it("discriminant", function() {
    const discriminant = QuadraticRealPolynomial_default.computeDiscriminant(
      1,
      2,
      3
    );
    expect(discriminant).toEqual(-8);
  });
  it("real roots throws without a", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeRealRoots();
    }).toThrowDeveloperError();
  });
  it("real roots throws without b", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeRealRoots(1);
    }).toThrowDeveloperError();
  });
  it("real roots throws without c", function() {
    expect(function() {
      QuadraticRealPolynomial_default.computeRealRoots(1, 1);
    }).toThrowDeveloperError();
  });
  it("negative b", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, -4, -6);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(-1);
    expect(roots[1]).toEqual(3);
  });
  it("positive b", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, 4, -6);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(-3);
    expect(roots[1]).toEqual(1);
  });
  it("marginally negative radical case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(
      2,
      -3.999999999999999,
      2
    );
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqualEpsilon(1, Math_default.EPSILON15);
    expect(roots[1]).toEqualEpsilon(1, Math_default.EPSILON15);
  });
  it("complex roots", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, -4, 6);
    expect(roots.length).toEqual(0);
  });
  it("intractable case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(0, 0, -3);
    expect(roots.length).toEqual(0);
  });
  it("linear case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(0, 2, 8);
    expect(roots.length).toEqual(1);
    expect(roots[0]).toEqual(-4);
  });
  it("2nd order monomial case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(3, 0, 0);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(0);
    expect(roots[1]).toEqual(0);
  });
  it("parabolic case with complex roots", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(3, 0, 18);
    expect(roots.length).toEqual(0);
  });
  it("parabolic case with real roots", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, 0, -18);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(-3);
    expect(roots[1]).toEqual(3);
  });
  it("zero and negative root case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, 6, 0);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(-3);
    expect(roots[1]).toEqual(0);
  });
  it("zero and positive root case", function() {
    const roots = QuadraticRealPolynomial_default.computeRealRoots(2, -6, 0);
    expect(roots.length).toEqual(2);
    expect(roots[0]).toEqual(0);
    expect(roots[1]).toEqual(3);
  });
});

