// packages/core/Specs/SphericalSpec.js
describe("Core/Spherical", function() {
  function NotSpherical(clock, cone, magnitude) {
    this.clock = clock;
    this.cone = cone;
    this.magnitude = magnitude;
  }
  NotSpherical.areEqual = function(left, right) {
    return left.clock === right.clock && left.cone === right.cone && left.magnitude === right.magnitude;
  };
  it("Default constructing sets properties to their expected values.", function() {
    const v3 = new Spherical_default();
    expect(v3.clock).toEqual(0);
    expect(v3.cone).toEqual(0);
    expect(v3.magnitude).toEqual(1);
  });
  it("Construtor parameters are assigned to the appropriate properties", function() {
    const v3 = new Spherical_default(1, 2, 3);
    expect(v3.clock).toEqual(1);
    expect(v3.cone).toEqual(2);
    expect(v3.magnitude).toEqual(3);
  });
  const fortyFiveDegrees = Math.PI / 4;
  const sixtyDegrees = Math.PI / 3;
  const cartesian11 = new Cartesian3_default(1, Math.sqrt(3), -2);
  const spherical = new Spherical_default(
    sixtyDegrees,
    fortyFiveDegrees + Math.PI / 2,
    Math.sqrt(8)
  );
  it("Can convert Cartesian3 to a new spherical instance", function() {
    expect(spherical).toEqualEpsilon(
      Spherical_default.fromCartesian3(cartesian11),
      Math_default.EPSILON15
    );
  });
  it("Can convert Cartesian3 to an existing spherical instance", function() {
    const existing = new Spherical_default();
    expect(spherical).toEqualEpsilon(
      Spherical_default.fromCartesian3(cartesian11, existing),
      Math_default.EPSILON15
    );
    expect(spherical).toEqualEpsilon(existing, Math_default.EPSILON15);
  });
  it("Cloning with no result parameter returns a new instance.", function() {
    const v3 = new Spherical_default(1, 2, 3);
    const clone2 = v3.clone();
    expect(clone2).not.toBe(v3);
    expect(clone2).toBeInstanceOf(Spherical_default);
    expect(clone2).toEqual(v3);
  });
  it("Cloning with result modifies existing instance and returns it.", function() {
    const v3 = new Spherical_default(1, 2, 3);
    const w = new NotSpherical();
    expect(NotSpherical.areEqual(v3, w)).toEqual(false);
    const clone2 = v3.clone(w);
    expect(clone2).not.toBe(v3);
    expect(clone2).toBe(w);
    expect(NotSpherical.areEqual(v3, w)).toEqual(true);
  });
  it("Normalizing with no result parameter creates new instance and sets magnitude to 1.0", function() {
    const v3 = new Spherical_default(0, 2, 3);
    const w = Spherical_default.normalize(v3);
    expect(w).not.toEqual(v3);
    expect(w.clock).toEqual(0);
    expect(w.cone).toEqual(2);
    expect(w.magnitude).toEqual(1);
  });
  it("Normalizing with result parameter modifies instance and sets magnitude to 1.0", function() {
    const v3 = new Spherical_default(0, 2, 3);
    const w = new NotSpherical();
    const q = Spherical_default.normalize(v3, w);
    expect(q).not.toEqual(v3);
    expect(q).toBe(w);
    expect(q.clock).toEqual(0);
    expect(q.cone).toEqual(2);
    expect(q.magnitude).toEqual(1);
  });
  it("Normalizing with this as result parameter modifies instance and sets magnitude to 1.0", function() {
    const v3 = new Spherical_default(0, 2, 3);
    const q = Spherical_default.normalize(v3, v3);
    expect(q).toBe(v3);
    expect(q.clock).toEqual(0);
    expect(q.cone).toEqual(2);
    expect(q.magnitude).toEqual(1);
  });
  it("equalsEpsilon returns true for expected values.", function() {
    expect(new Spherical_default(1, 2, 1)).toEqualEpsilon(new NotSpherical(1, 2, 1), 0);
    expect(new Spherical_default(1, 2, 1)).toEqualEpsilon(new NotSpherical(1, 2, 2), 1);
  });
  it("equalsEpsilon returns false for expected values.", function() {
    expect(new Spherical_default(1, 2, 1)).not.toEqualEpsilon(
      new NotSpherical(1, 2, 3),
      1
    );
  });
  it("toString returns the expected format.", function() {
    const v3 = new Spherical_default(1, 2, 3);
    expect(v3.toString()).toEqual("(1, 2, 3)");
  });
});

// packages/core/Specs/SplineSpec.js
describe("Core/Spline", function() {
  it("contructor throws", function() {
    expect(function() {
      return new Spline_default();
    }).toThrowDeveloperError();
  });
  it("wraps time that is out-of-bounds", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(spline.wrapTime(-0.5)).toEqual(1.5);
    expect(spline.wrapTime(2.5)).toEqual(0.5);
  });
  it("clamps time that is out-of-bounds", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(spline.clampTime(-0.5)).toEqual(0);
    expect(spline.clampTime(2.5)).toEqual(2);
  });
  it("wrapTime throws without a time", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(function() {
      spline.wrapTime();
    }).toThrowDeveloperError();
  });
  it("clampTime throws without a time", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(function() {
      spline.clampTime();
    }).toThrowDeveloperError();
  });
  it("findTimeInterval throws without a time", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(function() {
      spline.findTimeInterval();
    }).toThrowDeveloperError();
  });
  it("findTimeInterval throws when time is out of range", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [Cartesian3_default.ZERO, Cartesian3_default.UNIT_X, Cartesian3_default.UNIT_Y],
      times: [0, 1, 2]
    });
    expect(function() {
      spline.findTimeInterval(4);
    }).toThrowDeveloperError();
  });
  it("findTimeInterval", function() {
    const spline = HermiteSpline_default.createNaturalCubic({
      points: [
        Cartesian3_default.ZERO,
        Cartesian3_default.UNIT_X,
        Cartesian3_default.UNIT_Y,
        Cartesian3_default.UNIT_Z
      ],
      times: [0, 1, 2, 4]
    });
    const times = spline.times;
    expect(spline.findTimeInterval(times[0])).toEqual(0);
    expect(spline.findTimeInterval(times[1])).toEqual(1);
    expect(spline.findTimeInterval(times[0], 1)).toEqual(0);
    expect(spline.findTimeInterval(times[times.length - 2], 0)).toEqual(
      times.length - 2
    );
    expect(spline.findTimeInterval(times[0], times.length - 1)).toEqual(0);
  });
  it("getPointType throws for invalid point type", function() {
    expect(function() {
      Spline_default.getPointType({});
    }).toThrowDeveloperError();
  });
  it("getPointType", function() {
    expect(Spline_default.getPointType(1)).toEqual(Number);
    expect(Spline_default.getPointType(new Cartesian3_default())).not.toThrowDeveloperError();
    expect(Spline_default.getPointType(new Quaternion_default())).not.toThrowDeveloperError();
  });
});

